    Let things settle before proceeding, and add some more debug info/assertion.

    Differential Revision: https://phabricator.services.mozilla.com/D270468

diff --git a/calendar/test/CalendarTestUtils.sys.mjs b/calendar/test/CalendarTestUtils.sys.mjs
index 6bddfdc2eaa..c9f539a66f8 100644
--- a/calendar/test/CalendarTestUtils.sys.mjs
+++ b/calendar/test/CalendarTestUtils.sys.mjs
@@ -847,8 +847,13 @@ export const CalendarTestUtils = {
   async _editNewItem(win, target, type) {
     const dialogPromise = CalendarTestUtils.waitForEventDialog("edit");

+    await new Promise(resolve => win.requestIdleCallback(resolve));
     if (target) {
       this.scrollViewToTarget(target, true);
+      Assert.ok(
+        BrowserTestUtils.isVisible(target),
+        `click target ${target.id || target.localName} should be visible`
+      );
       await new Promise(resolve => win.setTimeout(resolve));
       EventUtils.synthesizeMouse(target, 1, 1, { clickCount: 2 }, win);
     } else {
diff --git a/calendar/test/browser/timezones/browser_timezones.js b/calendar/test/browser/timezones/browser_timezones.js
index c31b3a4de4f..1891c4498f6 100644
--- a/calendar/test/browser/timezones/browser_timezones.js
+++ b/calendar/test/browser/timezones/browser_timezones.js
@@ -70,7 +70,7 @@ add_setup(async () => {
   const time = cal.createDateTime();
   for (let i = 0; i < TIMEZONES.length; i++) {
     const eventBox = CalendarTestUtils.dayView.getHourBoxAt(window, i + 11);
-    info(`Checking content of hour box for <${TIMEZONES[i]}>.`);
+    info(`Checking content of hour box for <${TIMEZONES[i]}> at hour=${i + 11}`);
     const { dialogWindow, iframeWindow } = await CalendarTestUtils.editNewEvent(window, eventBox);
     time.hour = times[i][0];
     time.minute = times[i][1];
@@ -86,6 +86,7 @@ add_setup(async () => {

     info(`Saving event data for <${TIMEZONES[i]}> and closing item dialog.`);
     await saveAndCloseItemDialog(dialogWindow);
+    await new Promise(resolve => setTimeout(resolve));
   }
   info(`Completed setup for timezone test.`);
 });
